function validateCameraTimeline(samples){
 assert(samples.length>10,'Too few actual rendered frames');
 const distance=(a,b)=>Math.hypot(...a.map((v,i)=>v-b[i]));
 const close=(a,b,tolerance=1e-6)=>a.length===b.length&&a.every((v,i)=>Math.abs(v-b[i])<=tolerance);
 const first=samples[0],last=samples.at(-1);
 for(const f of samples){assert(f.frameOpacity>=.999&&f.canvasOpacity>=.999&&f.areaOpacity>=.999,'Fade/opacity dip during camera movement');assert.equal(f.cameraId,first.cameraId,'Rendered camera switched instead of moving continuously');for(const key of Object.keys(first.room))assert(close(f.room[key],first.room[key]),'Room object moved/scaled: '+key);}
 function checkTravel(label,frames){assert(frames.length>=6,'Not enough rendered '+label+' frames');const positions=frames.map(f=>f.cameraPosition),start=positions[0],end=positions.at(-1),total=distance(start,end);assert(total>.05,label+' camera position never moved');let maxStep=0,moved=0;for(let i=1;i<positions.length;i++){const step=distance(positions[i],positions[i-1]);if(step>1e-5)moved++;maxStep=Math.max(maxStep,step);}console.log(JSON.stringify({cameraTravel:label,renderedFrames:frames.length,movingSteps:moved,totalDistance:total,maxStep,start,end,changes:frames.filter((f,i)=>i&&distance(f.cameraPosition,frames[i-1].cameraPosition)>1e-5).map(f=>({phase:f.phase,stage:f.stage,elapsed:f.elapsed,position:f.cameraPosition}))}));assert(moved>=6,label+' lacks sustained intermediate camera movement');assert(maxStep<Math.max(.12,total*.55),label+' has a discontinuous camera jump');assert(distance(frames[0].cameraWorld,frames.at(-1).cameraWorld)>.01,label+' actual camera world matrix unchanged');console.log(label+': '+moved+' intermediate steps; max '+maxStep.toFixed(4)+' / travel '+total.toFixed(4));}
 function checkLens(label,frames){const a=frames[0].cameraProjection,b=frames.at(-1).cameraProjection,total=distance(a,b);let moved=0,maxStep=0;for(let i=1;i<frames.length;i++){const d=distance(frames[i-1].cameraProjection,frames[i].cameraProjection);if(d>1e-5)moved++;maxStep=Math.max(maxStep,d);}assert(total>.01&&moved>=6,label+' projection must change over sustained rendered frames');assert(maxStep<Math.max(.12,total*.55),label+' projection changed discontinuously');}const held=samples.filter(f=>f.phase==='playing');assert(held.length>=6&&held.at(-1).wallTime-held[0].wallTime>=1000,'Playing scene was not sustained');const playing=samples.findIndex(f=>f.phase==='playing'),returning=samples.findIndex(f=>f.phase==='returning');assert(playing>0&&returning>playing,'Missing complete entry/play/return timeline');checkTravel('entry',samples.slice(0,playing+1));checkTravel('return',samples.slice(returning));checkLens('entry',samples.slice(0,playing+1));checkLens('return',samples.slice(returning));assert(Math.abs(held.at(-1).cameraProjection[15])<1e-5&&held.at(-1).cameraProjection[11]<-.01,'Settled playing view did not reach live perspective projection');assert(close(last.cameraWorld,first.cameraWorld,1e-5),'Actual rendered camera did not restore');assert(close(last.cameraProjection,first.cameraProjection,1e-5),'Camera projection did not restore');
 const dist=(a,b)=>Math.hypot(a[12]-b[12],a[13]-b[13],a[14]-b[14]);let checked=0;
 for(const phase of ['face-step','reach','carry-turn','sit']){const frames=samples.filter(x=>x.phase==='seating'&&x.stage===phase&&x.arms?.length===2&&x.arms.every(a=>a.shoulder&&a.elbow&&a.hand));assert(frames.length,'No rendered entry stage: '+phase);for(const f of frames)for(const a of f.arms){assert(Math.abs(dist(a.shoulder,a.elbow)-.22)<.001,'Upper arm proportion changed in '+phase);assert(Math.abs(dist(a.elbow,a.hand)-.18)<.001,'Forearm proportion changed in '+phase);checked++;}}
 const standingExit=samples.filter(f=>f.phase==='egress'&&f.stage==='step-clear');assert(standingExit.length>=4,'No visible step-clear egress frames');assert(Math.hypot(...standingExit.at(-1).physical.actor.map((v,i)=>v-standingExit[0].physical.actor[i]))>.15,'Step-clear did not visibly move avatar');assert(standingExit.every(f=>!f.physical.controls),'Controls appeared during step-clear');assert(standingExit.every(f=>f.physical.colliderMargin>=-.001),'Step-clear path crossed solid stool');const lastEgress=samples.findLastIndex(f=>f.phase==='egress');const unlocked=samples.slice(lastEgress+1).find(f=>f.phase===null&&f.physical.controls);assert(unlocked&&unlocked.physical.colliderMargin>=-.001,'Controls unlocked inside stool collider');assert(Math.abs(unlocked.physical.actor[0]+1.85)<.015&&Math.abs(unlocked.physical.actor[2]-.0604802968)<.015,'Unlocked before reaching safe egress endpoint');console.log('Continuous WebGL camera, stationary room, no fade; '+checked+' fixed-length arm checks');
}
function validateOutdoorTiming(samples){const early=samples.filter(f=>f.phase==='seating'&&f.elapsed<1750);assert(early.length>=6,'No pickup timeline observed');assert(early.every(f=>f.outdoor.amount<1e-6&&!f.outdoor.visible),'Exterior changed during pickup before camera transition');const entry=samples.filter(f=>f.phase==='seating'&&f.elapsed>=1750),blend=entry.filter(f=>f.outdoor.amount>.01&&f.outdoor.amount<.99);assert(blend.length>=6,'Exterior did not crossfade over multiple real camera frames');for(const f of entry){assert(Math.abs(f.outdoor.amount-f.outdoor.lens)<1e-6,'Exterior fade not synchronized with actual rendered camera lens');assert(f.outdoor.cameraStarted,'Exterior blend before camera start');}const first=blend[0],last=blend.at(-1);assert(Math.hypot(...last.cameraPosition.map((v,i)=>v-first.cameraPosition[i]))>.1,'Exterior blended without actual camera motion');const returning=samples.filter(f=>f.phase==='returning');assert(returning.length>6);for(const f of returning)assert(Math.abs(f.outdoor.amount-Math.max(0,1-f.elapsed/900))<1e-5,'Existing 900ms return outdoor timing changed');const held=samples.filter(f=>f.phase==='playing');assert(held.every(f=>Math.abs(f.outdoor.amount-1)<1e-5),'Playing exterior not fully revealed');console.log('026 outdoor blend: pickup held, '+blend.length+' camera-synchronized frames, return900ms preserved');}
function validate026Sun(light){assert(light,'Window sunlight light missing');assert(light.t>0&&light.t<1,'Sunlight does not pass through window into room');const[x,y,z]=light.crossLocal;assert(Math.abs(x)<.66&&y>.20&&y<.93+Math.sqrt(Math.max(0,.76*.76-x*x))-.10,'Sunlight enters through wall instead of arched aperture');assert(Math.hypot(x,y-.88,z-.08)<1e-5,'Sunlight ray misaligned with window center');const e=light.effect;assert(e?.visible&&e.opacity>=.15&&e.opacity<=.35&&e.additive&&e.textured&&e.depthTest,'Restored visible window rays missing or imperceptible');const points=e.vertices.filter((p,i,a)=>!a.slice(0,i).some(q=>Math.hypot(...p.map((v,k)=>v-q[k]))<1e-5));assert(points.length>=4,'Sunray sheet has no meaningful area');const anchor=points.filter(p=>Math.abs(p[2]+2.025)<.005),far=points.filter(p=>p[2]>-1);assert(anchor.length>=2&&far.length>=2,'Sunrays are not extruded from aperture into room');for(const p of anchor){const lx=p[0]-e.windowPosition[0],ly=p[1]-e.windowPosition[1];assert(Math.abs(lx)<.76&&ly>.1&&ly<.93+Math.sqrt(Math.max(0,.76*.76-lx*lx)),'Ray upper edge not inside actual aperture');}const dir=light.target.map((v,i)=>v-light.source[i]),len=Math.hypot(...dir);for(const p of far){const best=Math.max(...anchor.map(q=>{const v=p.map((x,i)=>x-q[i]);return v.reduce((a,x,i)=>a+x*dir[i],0)/(Math.hypot(...v)*len)}));assert(best>.9999,'Visible sunlight sheet not aligned with actual sun direction');}assert(e.projected.some(p=>Math.abs(p[0])<1&&Math.abs(p[1])<1),'Visible sunlight effect remains outside final camera');}
function validate026Framing(f){const close=(a,b)=>a.every((v,i)=>Math.abs(v-b[i])<1e-5);assert(close(f.actualPosition,f.expectedPosition),'Performance camera must translate only responsive camera-left amount from025');assert(Math.abs(Math.abs(f.actualQuaternion.reduce((v,x,i)=>v+x*f.expectedQuaternion[i],0))-1)<1e-6,'026 camera orientation changed');assert(Math.abs(f.actualFov-f.expectedFov)<1e-5,'026 camera FOV widened/changed');assert(Math.abs(f.actualZoom-f.expectedZoom)<1e-5,'026 camera zoom changed');assert(f.leftShift>0&&f.leftShift<=.120001,'Camera-left shift must remain positive and at most .12m');assert(f.offAxis<1e-5,'Camera moved off its original horizontal view plane');if(f.viewportWidth>=600&&f.availableMargin>=.12)assert(Math.abs(f.leftShift-.12)<1e-6,'Available desktop margin should retain full .12m shift');assert(f.projectedWindow.length===2&&f.projectedWindow.every(o=>o&&o.min.every(v=>v>=-1.001)&&o.max.every(v=>v<=1.001)),'Actual complete arched frame or sill is clipped');}
function validate027Framing(m){const portrait=m.viewport.aspect<=1.2,close=(a,b)=>a.every((v,i)=>Math.abs(v-b[i])<1e-5);assert(m.window.length===2&&m.window.every(o=>o&&o.min.every(v=>v>=-1.001)&&o.max.every(v=>v<=1.001)),'028 full actual window frame/sill clipped');if(portrait){const b=m.baseline027Camera;assert(close(m.actualCamera.position,b.position),'028 changed accepted portrait camera position');assert(Math.abs(Math.abs(m.actualCamera.quaternion.reduce((v,x,i)=>v+x*b.quaternion[i],0))-1)<1e-6,'028 changed accepted portrait camera angle');assert(Math.abs(m.actualCamera.fov-b.fov)<1e-5&&Math.abs(m.actualCamera.zoom-b.zoom)<1e-5,'028 changed accepted portrait lens');assert(m.actual.head.visibleVertexFraction>=.60&&m.actual.cello.visibleVertexFraction>=.70,'028 regressed portrait performer/cello visibility');}console.log(JSON.stringify({framing028:m.viewport,head:m.actual.head.visibleVertexFraction,cello:m.actual.cello.visibleVertexFraction}));}
function validate028ArchitectureTimeline(samples){for(const f of samples){const a=f.architecture028;assert(a,'Missing architectural telemetry');assert(Math.abs(a.mountOpacity-a.lens)<1e-5,'Curtain mounts not synchronized with camera projection');assert(a.wallsVisible===(a.lens>0)&&a.mountsVisible===(a.lens>0),'Wall/mount presence jumped out of camera transition');}}
function validate028View(v){const near=(a,b)=>Math.abs(a-b)<.003,overlap=(a,b)=>a.min.every((x,i)=>x<=b.max[i]+.02&&a.max[i]>=b.min[i]-.02);if(v.aspect>=1.4)assert(v.vanity.clippedArea<1e-6&&v.vanity.visibleTriangles===0,'Wide performance still shows dressing table/mirror geometry');assert(v.extensions.length===2,'Missing connected wall extensions');for(const w of v.extensions){assert(w.visible&&w.sameMaterial,'Wall extension must use original visible wall material');assert(near(w.box.min[0],w.source.min[0])&&near(w.box.max[0],w.source.max[0])&&near(w.box.min[2],w.source.min[2])&&near(w.box.max[2],w.source.max[2]),'Extension disconnected horizontally from actual wall');assert(near(w.box.min[1],w.source.max[1])&&near(w.box.max[1],7),'Wall extension is floating or not tall enough');assert(Math.min(w.box.max[0]-w.box.min[0],w.box.max[2]-w.box.min[2])<.35&&w.box.max[1]-w.box.min[1]>2,'Extension is a horizontal roof, not vertical wall');}assert(v.topCoverage.every(r=>r.wall),'Empty/background area remains above room');assert(v.mountParts.length===6&&v.rod,'Missing true curtain wall brackets');const rear=v.extensions.find(w=>w.name.startsWith('rear')).source;let seen=0;for(const side of['left','right']){const get=suffix=>v.mountParts.find(m=>m.name==='curtain-mount-'+side+'-'+suffix),plate=get('rosette'),arm=get('return'),saddle=get('saddle');assert(plate&&arm&&saddle&&[plate,arm,saddle].every(m=>m.visible&&m.opacity>.99),'Bracket is absent/transparent');assert(near(plate.box.min[2],rear.max[2]),'Bracket plate not flush to actual plaster');assert(overlap(plate.box,arm.box)&&overlap(arm.box,saddle.box)&&overlap(saddle.box,v.rod),'Bracket does not physically connect wall to rod');if([plate,arm,saddle].some(m=>m.projected.some(q=>Math.abs(q[0])<1&&Math.abs(q[1])<1)))seen++;}assert(seen>0,'No mounted curtain hardware visible in shot');}
