async function wideVariants028(label){for(const[width,height]of[[1440,900],[1024,768]]){await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:false});await sleep(120);await until('__cello028Inspect().viewportWidth==='+width+'&&__cello028Inspect().settled','wide resized composition');await inspect028(label+'-'+width+'x'+height);const m=await evaluate('__cello027Metrics()');validate027Framing(m);await snapshot(label+'-'+width+'x'+height);}await send('Emulation.setDeviceMetricsOverride',{width:1180,height:757,deviceScaleFactor:1,mobile:false});await sleep(120);await until('__cello028Inspect().viewportWidth===1180&&__cello028Inspect().settled','restore baseline performance framing');const clip=await evaluate('(()=>{const r=document.querySelector("#scene").getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:Math.min(r.height*.45,300),scale:2}})()');const image=await send('Page.captureScreenshot',{format:'png',clip});await fsp.writeFile(path.join(artifacts,label+'-curtain-mounts-2x.png'),Buffer.from(image.data,'base64'));}
function assertPermanentStool(actual,expected,label){assert(actual?.visible,label+': permanent stool missing or hidden');assert(actual.stationMeshes>0,label+': stool lacks cello station hit target');if(expected){assert.equal(actual.uuid,expected.uuid,label+': stool object was replaced');assert(actual.world.every((v,i)=>Math.abs(v-expected.world[i])<1e-6),label+': permanent stool moved/scaled');}}
