(async()=>{await fsp.mkdir(artifacts,{recursive:true});assert(fs.existsSync(path.join(root,base==='/'?'index.html':'3D/index.html')),'Supply site root or 3D directory');server=http.createServer(async(req,res)=>{try{let p=decodeURIComponent(new URL(req.url,'http://local').pathname);if(p.endsWith('/'))p+='index.html';const file=path.resolve(root,'.'+p);if(!file.startsWith(root+path.sep))throw Error('Forbidden');let body=await fsp.readFile(file);if(path.basename(file)==='app.js')body=Buffer.concat([body,Buffer.from(hook)]);const mime={'.html':'text/html','.js':'text/javascript','.css':'text/css','.webp':'image/webp','.png':'image/png','.svg':'image/svg+xml','.json':'application/json'}[path.extname(file)]||'application/octet-stream';res.writeHead(200,{'Content-Type':mime,'Cache-Control':'no-store'});res.end(body);}catch{res.writeHead(404);res.end('Not found');}});await new Promise(r=>server.listen(0,'127.0.0.1',r));origin=`http://127.0.0.1:${server.address().port}`;profile=await fsp.mkdtemp(path.join(os.tmpdir(),'cello-chrome-'));const executable=process.env.CHROME_PATH||['/usr/bin/google-chrome','/usr/bin/google-chrome-stable','/usr/bin/chromium','/usr/bin/chromium-browser'].find(p=>fs.existsSync(p));assert(executable,'Chrome not found; set CHROME_PATH');browser=spawn(executable,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--remote-debugging-port=0','--remote-allow-origins=*',`--user-data-dir=${profile}`,'about:blank'],{stdio:['ignore','ignore','pipe']});let chromeLog='';browser.stderr.on('data',b=>chromeLog+=b);browser.on('error',e=>faults.push('Chrome: '+e.message));let port;for(let i=0;i<350;i++){try{port=(await fsp.readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}if(browser.exitCode!==null)throw Error('Chrome exited: '+chromeLog);await sleep(100);}assert(port,'Chrome startup timeout: '+chromeLog);const target=await(await fetch(`http://127.0.0.1:${port}/json/new?about:blank`,{method:'PUT'})).json();ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((resolve,reject)=>{ws.addEventListener('open',resolve,{once:true});ws.addEventListener('error',reject,{once:true});});ws.addEventListener('message',event=>{const m=JSON.parse(event.data);if(m.id){const q=pending.get(m.id);if(q){clearTimeout(q.timer);pending.delete(m.id);m.error?q.reject(Error(JSON.stringify(m.error))):q.resolve(m.result);}return;}if(m.method==='Page.screencastFrame'){send('Page.screencastFrameAck',{sessionId:m.params.sessionId}).catch(e=>faults.push('Screencast ack: '+e.message));const capture=entranceCapture;if(capture){const file=capture.label+'-entrance-'+String(capture.frameCount++%150).padStart(3,'0')+'.jpg';capture.frames.push({file,...m.params.metadata});if(capture.frames.length>150)capture.frames.shift();capture.writes.push(fsp.writeFile(path.join(artifacts,file),Buffer.from(m.params.data,'base64')));}return;}if(m.method==='Runtime.exceptionThrown')faults.push(JSON.stringify(m.params.exceptionDetails));if(m.method==='Runtime.consoleAPICalled'&&m.params.type==='error')faults.push(m.params.args.map(a=>a.value||a.description).join(' '));if(m.method==='Network.responseReceived'){const r=m.params.response;resources.add(new URL(r.url).pathname);if(r.status>=400&&!r.url.endsWith('/favicon.ico'))faults.push(`HTTP ${r.status}: ${r.url}`);}if(m.method==='Network.loadingFailed'&&!m.params.canceled)faults.push('Network: '+m.params.errorText);});await send('Page.enable');await send('Runtime.enable');await send('Network.enable');await runCase(1180,757,false,2);await runCase(360,800,false);await runCase(390,844,false);await runCase(768,1024,false);await runCase(390,844,true);await runDoorArrival();for(const resource of ['room-polish.js','window-landscape.js','rural-window.webp'])assert([...resources].some(p=>p.endsWith('/'+resource)),'Resource not loaded: '+resource);assert.deepEqual(faults,[],'Browser faults');console.log(JSON.stringify({ok:true,results,resources:[...resources]},null,2));await fsp.writeFile(path.join(artifacts,'result.json'),JSON.stringify({ok:true,results,resources:[...resources]},null,2));})().catch(async error=>{console.error(error.stack);if(ws?.readyState===1)try{await fsp.writeFile(path.join(artifacts,'failure-physical-timelines.json'),JSON.stringify(await evaluate('({navigation:globalThis.__celloNavigationEvidence,door:globalThis.__celloDoorEvidence})'),null,2));}catch{}if(entranceCapture&&ws?.readyState===1)try{await stopEntranceEvidence(false);}catch{}if(ws?.readyState===1)try{await snapshot('failure');}catch{}await fsp.mkdir(artifacts,{recursive:true});await fsp.writeFile(path.join(artifacts,'result.json'),JSON.stringify({ok:false,error:error.stack,faults,results},null,2));process.exitCode=1;}).finally(async()=>{for(const q of pending.values()){clearTimeout(q.timer);q.reject(Error('Test ended'));}pending.clear();ws?.close();browser?.kill('SIGKILL');server?.close();if(profile)await fsp.rm(profile,{recursive:true,force:true}).catch(()=>{});});
